<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { buscarCuentasPadre, cambiarEstadoCuentaContable, guardarCuentaContable, listarCuentasContables } from '../services/cuentasContables'
import type { CuentaContable, CuentaContableOption, CuentaContablePayload, TipoRequerimientoCuenta } from '../interfaces/cuentasContables.interface'
const rows=ref<CuentaContable[]>([]),criterio=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null),parentQuery=ref(''),parentResults=ref<CuentaContableOption[]>([])
const blank=():CuentaContablePayload=>({cta_contable:'',descripcion:'',naturaleza:'D',tipo_balance:null,nivel:1,cuenta_padre_id:null,cta_presupuestal:null,cta_ajuste_correccion_monetaria:null,cta_equivalente:null,cod_snip:null,fuente_financiamiento:null,es_cuenta_costos:false,req_centro_costos:false,es_cuenta_orden:false,req_cuenta_orden:false,es_cuenta_acm:false,req_cuenta_acm:false,req_cuenta_pptal:false,tipo_req_codigo:'none',req_costo_abc:false,act_rec_fin:false,es_tesoreria:false,movimiento:false})
const form=reactive<CuentaContablePayload>(blank()),parentText=ref('')
const flags:{key:keyof CuentaContablePayload;label:string}[]=[{key:'es_cuenta_costos',label:'Es cuenta de costos'},{key:'req_centro_costos',label:'Requiere centro de costos'},{key:'req_costo_abc',label:'Requiere costo ABC'},{key:'es_cuenta_orden',label:'Es cuenta de orden'},{key:'req_cuenta_orden',label:'Requiere cuenta de orden'},{key:'es_cuenta_acm',label:'Es cuenta ACM'},{key:'req_cuenta_acm',label:'Requiere cuenta ACM'},{key:'req_cuenta_pptal',label:'Requiere cuenta presupuestal'},{key:'movimiento',label:'Cuenta de movimiento'},{key:'act_rec_fin',label:'Actividad/recurso financiero'},{key:'es_tesoreria',label:'Es tesorería'}]
const requirements:{value:TipoRequerimientoCuenta;label:string}[]=[{value:'none',label:'Ninguno'},{value:'trabajador',label:'Trabajador'},{value:'proveedor',label:'Proveedor'},{value:'inv',label:'Inversión'},{value:'entidad',label:'Entidad'}]
const message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la operación.'
async function load(next=1){loading.value=true;error.value='';try{const r=await listarCuentasContables(criterio.value,next);rows.value=r.data;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total}catch(v){error.value=message(v)}finally{loading.value=false}}
function reqType(item:CuentaContable):TipoRequerimientoCuenta{return item.req_cod_trabajador?'trabajador':item.req_cod_proveedor?'proveedor':item.req_cod_inv?'inv':item.req_cod_entidad?'entidad':'none'}
function open(item?:CuentaContable){editing.value=item?.id??null;Object.assign(form,blank(),item?{...item,tipo_req_codigo:reqType(item)}:{});parentText.value=item?.cuenta_padre?`${item.cuenta_padre.cta_contable} - ${item.cuenta_padre.descripcion}`:'';parentQuery.value='';parentResults.value=[];error.value='';modal.value=true}
async function searchParent(){if(!parentQuery.value.trim())return;try{parentResults.value=(await buscarCuentasPadre(parentQuery.value.trim())).filter(x=>x.id!==editing.value)}catch(v){error.value=message(v)}}
function chooseParent(item:CuentaContableOption){form.cuenta_padre_id=item.id;parentText.value=`${item.cta_contable} - ${item.descripcion}`;parentResults.value=[]}
async function save(){if(!form.cta_contable.trim())return void(error.value='La cuenta contable es obligatoria.');const desc=form.descripcion.trim();if(desc.length<3||desc.length>100)return void(error.value='La descripción debe tener entre 3 y 100 caracteres.');if(form.nivel<1||form.nivel>10)return void(error.value='El nivel debe estar entre 1 y 10.');saving.value=true;try{const nullable=(v:string|null)=>v?.trim()||null;await guardarCuentaContable(editing.value,{...form,cta_contable:form.cta_contable.trim(),descripcion:desc.toUpperCase(),cta_presupuestal:nullable(form.cta_presupuestal),cta_ajuste_correccion_monetaria:nullable(form.cta_ajuste_correccion_monetaria),cta_equivalente:nullable(form.cta_equivalente),cod_snip:nullable(form.cod_snip)});modal.value=false;success.value=`Cuenta ${editing.value?'actualizada':'registrada'} correctamente.`;await load(editing.value?page.value:1)}catch(v){error.value=message(v)}finally{saving.value=false}}
async function toggle(item:CuentaContable){if(!confirm(`¿Desea ${item.activa?'desactivar':'activar'} la cuenta ${item.cta_contable}?`))return;try{await cambiarEstadoCuentaContable(item.id);await load(page.value)}catch(v){error.value=message(v)}}
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/administracion/contabilidad">Contabilidad</RouterLink> / Cuentas contables</nav><header class="hero"><div class="mark">CC</div><div><small>MIA · CONTABILIDAD · MAESTROS</small><h1>Plan de cuentas</h1><p>Administra la estructura y configuración operativa de las cuentas contables.</p></div><strong>{{total}} cuentas</strong><button @click="open()">+ Nueva cuenta</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><form class="filters" @submit.prevent="load(1)"><input v-model.trim="criterio" placeholder="Buscar por cuenta o descripción"><button>Buscar</button><button type="button" class="soft" @click="criterio='';load(1)">Limpiar</button></form><section class="table-card"><div v-if="loading" class="empty">Consultando cuentas…</div><div v-else-if="!rows.length" class="empty">No se encontraron cuentas.</div><div v-else class="scroll"><table><thead><tr><th>Cuenta</th><th>Descripción</th><th>Nivel</th><th>Cuenta padre</th><th>Naturaleza</th><th>Balance</th><th>Movimiento</th><th>Tesorería</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td><b>{{item.cta_contable}}</b></td><td>{{item.descripcion}}</td><td>{{item.nivel}}</td><td>{{item.cuenta_padre?`${item.cuenta_padre.cta_contable} - ${item.cuenta_padre.descripcion}`:'—'}}</td><td>{{item.naturaleza_label||(item.naturaleza==='D'?'Deudora':'Acreedora')}}</td><td>{{item.tipo_balance||'—'}}</td><td>{{item.movimiento?'Sí':'No'}}</td><td>{{item.es_tesoreria?'Sí':'No'}}</td><td><span :class="item.activa?'ok':'bad'">{{item.activa?'Activa':'Inactiva'}}</span></td><td class="actions"><button class="edit" @click="open(item)">Editar</button><button class="soft" @click="toggle(item)">Estado</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div><small>CUENTA CONTABLE</small><h2>{{editing?'Editar':'Nueva'}} cuenta</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Cuenta *<input v-model="form.cta_contable" maxlength="45"></label><label class="span2">Descripción *<input v-model="form.descripcion" maxlength="100" @input="form.descripcion=form.descripcion.toUpperCase()"></label><label>Nivel *<input v-model.number="form.nivel" type="number" min="1" max="10"></label><label>Naturaleza *<select v-model="form.naturaleza"><option value="D">Deudora</option><option value="H">Acreedora</option></select></label><label>Tipo balance<select v-model="form.tipo_balance"><option :value="null">Sin tipo</option><option>ACTIVO</option><option>PASIVO</option><option>PATRIMONIO</option></select></label><label>Fuente<select v-model="form.fuente_financiamiento"><option :value="null">Sin fuente</option><option value="RDR">RDR</option><option value="RO">RO</option></select></label><label class="span2">Buscar cuenta padre<input v-model="parentQuery" placeholder="Código o descripción" @keyup.enter.prevent="searchParent"><button type="button" @click="searchParent">Buscar</button></label><p v-if="parentText" class="selected-parent">✓ {{parentText}} <button type="button" @click="form.cuenta_padre_id=null;parentText=''">Quitar</button></p><div v-if="parentResults.length" class="results span3"><button v-for="item in parentResults" :key="item.id" type="button" @click="chooseParent(item)"><b>{{item.cta_contable}}</b> {{item.descripcion}}</button></div><label>Cta. presupuestal<input v-model="form.cta_presupuestal" maxlength="45"></label><label>Cta. equivalente<input v-model="form.cta_equivalente" maxlength="45"></label><label>Cta. ajuste monetario<input v-model="form.cta_ajuste_correccion_monetaria" maxlength="45"></label><label>Código SNIP<input v-model="form.cod_snip" maxlength="45"></label><label class="span2">Requerir código de<select v-model="form.tipo_req_codigo"><option v-for="r in requirements" :key="r.value" :value="r.value">{{r.label}}</option></select></label></div><h3>Configuración de la cuenta</h3><div class="checks"><label v-for="flag in flags" :key="flag.key"><input v-model="form[flag.key]" type="checkbox"> {{flag.label}}</label></div><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">Guardar</button></footer></form></div></div></template>
<style scoped>
.page{--a:#385d8a;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--a);text-decoration:none}.hero{padding:20px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--a);border-radius:12px;background:#fff}.mark{width:48px;height:48px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--a);font-weight:800}.hero small,.dialog small{color:var(--a);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.hero strong{margin-left:auto;font-size:.55rem}.hero button,.filters button,.table-card footer button,.dialog button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.5rem}.flash{padding:9px;border-radius:7px;font-size:.6rem}.success{color:#287052;background:#edf9f3}.error{color:#a64046;background:#fff0f0}.filters{margin-top:10px;padding:13px;display:flex;gap:7px;background:#fff}.filters input,.dialog input,.dialog select{width:100%;box-sizing:border-box;padding:8px;border:1px solid #d7dfe2;border-radius:6px;font:inherit;font-size:.52rem}.filters input{margin-right:auto}.soft{color:#64727a!important;background:#edf1f3!important}.table-card{margin-top:10px;background:#fff;overflow:hidden}.scroll{overflow:auto}table{width:100%;min-width:1250px;border-collapse:collapse;font-size:.5rem}th,td{padding:9px;border-bottom:1px solid #e8ecee;text-align:left}th{color:#fff;background:#4c627e}.ok,.bad{padding:3px 6px;border-radius:10px}.ok{color:#287154;background:#e6f7ee}.bad{color:#9d4046;background:#fdebed}.actions{display:flex;gap:3px}.actions button{padding:5px;border:0;border-radius:4px;font-size:.43rem}.edit{color:#385d8a;background:#e8eff8}.empty{padding:45px;text-align:center}.table-card>footer{padding:10px;display:flex;justify-content:center;gap:9px}.backdrop{position:fixed;z-index:100;inset:0;padding:18px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(900px,100%);max-height:94vh;overflow:auto;padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex;justify-content:space-between}.dialog h2{margin:3px 0 14px;font-size:.9rem}.dialog h3{font-size:.65rem}.dialog>header button{color:#59666c;background:none;font-size:1.1rem}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.grid label{display:grid;gap:4px;font-size:.48rem}.span2{grid-column:span 2}.span3{grid-column:span 3}.results{max-height:130px;overflow:auto}.results button{width:100%;display:block;color:#35464e;background:#f2f5f7;text-align:left}.selected-parent{grid-column:span 3;padding:7px;color:#287154;background:#e6f7ee;font-size:.5rem}.checks{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;padding:10px;background:#f6f8f9}.checks label{font-size:.5rem}.checks input{width:auto}.dialog footer{margin-top:15px;display:flex;justify-content:flex-end;gap:6px}@media(max-width:720px){.hero,.filters{flex-wrap:wrap}.grid,.checks{grid-template-columns:1fr}.span2,.span3,.selected-parent{grid-column:auto}}
</style>
